const SKIN_ALT_NAME = ['white', 'black', 'blue', 'red', 'green', 'grey']


let output = new Map<string, Set<string>>()

function skinAlt(path:string) {
    let ret = {
        skinAlt:"",
        skinRemovedAlt:path
    }

    for(const skin_alt of SKIN_ALT_NAME){
        if(path.endsWith("_" + skin_alt + ".png")){
            ret.skinAlt = skin_alt
            ret.skinRemovedAlt = path.substring(0, path.length - 1 - skin_alt.length - 4) + ".png"
        }
    }
    return ret
}

let re = new RegExp("^(.*/gfx/characters/costumes)_[a-z]+(/.*)$")
function handle(path:string, chara:string){
    let orig_from = skinAlt(path)

    let orig_path = orig_from.skinRemovedAlt
    let m = re.exec(orig_path)
    if(m){
        orig_path = m[1]! + m[2]!
    }

    let dlc3 = ""
    let dlc3_index = orig_path.indexOf("-dlc3/")
    if(dlc3_index > 0){
        orig_path = orig_path.substring(0, dlc3_index) + orig_path.substring(dlc3_index+5)
        dlc3 = "dlc3"
    }

    if(!output.has(orig_path))
        output.set(orig_path, new Set())
    output.get(orig_path)!.add(dlc3 + ":" + chara + ":" + orig_from.skinAlt)
}

for(const [chara, maps] of m){
    for(const [from, to] of maps){
        handle(from, chara)
        handle(to, chara)
    }
}

let datas = []

for(const [path, set] of output){
    datas.push([
        path, Array.from(set).join(";")
    ])
}


let json_output = {
    "description": {
        "zh": "有update_costumes.py自动生成"
    },
    "schema": {
        "fields": [
            {
                "name": "sprite_path",
                "type": "string",
                "title": {
                    "en": "sprite_path",
                    "zh": "贴图路径"
                }
            },
            {
                "name": "characolors",
                "type": "string",
                "title": {
                    "en": "characolors[]",
                    "zh": "角色颜色组合信息"
                }
            }
        ]
    },
    "data": datas
}

writeFileSync("CharaCostume.tabx", JSON.stringify(json_output))